Q: Vue $attrs fallthrough attribute: How can I use intellisense to get suggestions for the properties of the attributes? A: <p>Here is an example how I have both IntelliSense for props and attributes fallthrough</p>
<pre class="lang-js prettyprint-override"><code>&lt;script lang=&quot;ts&quot; setup&gt;
import { useAttrs, type InputHTMLAttributes } from 'vue'

/**
 * Props type definition strategy:
 *
 * We use InputHTMLAttributes to provide native-like IntelliSense when using this component,
 * allowing users to pass any standard HTML input attributes (&quot;type&quot;, &quot;class&quot;, &quot;id&quot;, etc.).
 *
 * Due to Vue's SFC compiler limitation with complex type inheritance, we use @vue-ignore
 * to suppress the &quot;Failed to resolve extends base type&quot; error. This causes properties from
 * InputHTMLAttributes to be treated as fallthrough attrs at runtime rather than props.
 *
 * RuntimeProps: Explicitly declared props that are available in the props object
 * IgnoredProps: Properties from InputHTMLAttributes that become fallthrough attrs
 *
 * @example
 * ```vue
 * &lt;BaseInput
 *   v-model=&quot;event.title&quot;
 *   caption=&quot;Title&quot;
 *   type=&quot;text&quot;
 *   id=&quot;title-input&quot;
 *   class=&quot;field&quot;
 *   name=&quot;title&quot;
 *   required
 * /&gt;
 * ```
 */
type RuntimeProps = { caption: string }
type IgnoredProps = /* @vue-ignore */ InputHTMLAttributes
type Props = RuntimeProps &amp; IgnoredProps

const props = defineProps&lt;Props&gt;()
const model = defineModel&lt;string | number&gt;({ required: true })

/**
 * Fallthrough attributes access:
 *
 * Properties from InputHTMLAttributes (due to @vue-ignore) are not available in props.
 * They are passed as fallthrough attrs and must be accessed via useAttrs().
 *
 * We cast to Partial&lt;InputHTMLAttributes&gt; to provide type safety when accessing
 * these attributes (e.g., attrs.id, attrs.type, attrs.class).
 */
const attrs = useAttrs() as Partial&lt;InputHTMLAttributes&gt;
&lt;/script&gt;

&lt;template&gt;
  &lt;!--
    Component structure:
    - Custom props (&quot;caption&quot;) are accessed via props object
    - HTML input attributes (&quot;id&quot;, &quot;type&quot;, &quot;class&quot;, etc.) are accessed via attrs
  --&gt;
  &lt;label :for=&quot;attrs.id&quot;&gt;{{ props.caption }}&lt;/label&gt;
  &lt;input v-model=&quot;model&quot; v-bind=&quot;attrs&quot; /&gt;
&lt;/template&gt;
</code></pre>
